SELECT 'batch_030_2c4cb6bc_wav_14' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-093f74ab-8b9','sm-upload-42481750-586','sm-upload-4438c1e4-e9b','sm-upload-4663e1f2-1e1','sm-upload-4a92f357-06e','sm-upload-58a0f37c-7c7','sm-upload-5ca7125b-fa4','sm-upload-61fbaa65-987','sm-upload-64e68350-1e0','sm-upload-a68ccf5a-864','sm-upload-bc3bb5a0-94b','sm-upload-cab08fa5-c3a','sm-upload-f1c183f2-879','sm-upload-f2cf4e7c-18e') AND album_id='al-e2b6feeda9f07f575b32fadf2c4cb6bc') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-093f74ab-8b9','sm-upload-42481750-586','sm-upload-4438c1e4-e9b','sm-upload-4663e1f2-1e1','sm-upload-4a92f357-06e','sm-upload-58a0f37c-7c7','sm-upload-5ca7125b-fa4','sm-upload-61fbaa65-987','sm-upload-64e68350-1e0','sm-upload-a68ccf5a-864','sm-upload-bc3bb5a0-94b','sm-upload-cab08fa5-c3a','sm-upload-f1c183f2-879','sm-upload-f2cf4e7c-18e') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-e2b6feeda9f07f575b32fadf2c4cb6bc' AND name='黑猫出现在白天-七点半') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-e2b6feeda9f07f575b32fadf2c4cb6bc') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-e2b6feeda9f07f575b32fadf2c4cb6bc') AS calculated_size;
